"""Render the complete schema example inventory; --check rejects stale docs."""
import argparse
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / 'src'))
from inspection_api import api_schema


def render():
    schema = api_schema()
    lines = [
        '# API examples: complete inventory', '',
        'Generated by `python3 tools/generate-api-examples.py`; do not edit manually.', '',
        '[Practical scenarios and expected errors](INSPECTION_COOKBOOK.md).', '',
        'These micro-examples cover every public member of the typed schema.',
        'The callback provides `api`. Examples using `part` assume an H2',
        'HEADERS part with decoded headers; `entry` is one of its HPACK entries.',
        'Each block is a separate example, not a step in one continuous script.', '',
        'Commit defaults to `Safety.Easy`; `safety=Safety.Expert` is an explicit',
        'choice for one commit. It does not set Rewrite/Translate or the next callback mode.',
        'Each member below documents its Easy and Expert rules separately.', '',
    ]
    for name, definition in schema['types'].items():
        lines.extend([f'## {name}', '', definition['description'] or '', ''])
        members = definition['fields'] + definition['methods']
        if not members:
            lines.extend(['This type has no public schema members; see the cookbook for practical usage.', ''])
        for member in members:
            lines.extend([
                f"### {name}.{member['name']}", '', member['description'], '',
                f"Availability: {member['availability']}", '',
                f"Access: {member['access']}; type/result: `{member['type']}`.", '',
                f"Easy: {member['easy']}", '', f"Expert: {member['expert']}", '',
                '```python', member['example'], '```', '',
            ])
    return '\n'.join(lines)


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    target = ROOT / 'docs/API_EXAMPLES_REFERENCE.md'
    content = render()
    if args.check:
        if not target.exists() or target.read_text() != content:
            raise SystemExit('API example inventory is stale; run tools/generate-api-examples.py')
    else:
        target.write_text(content)
